#[test]
fn const_new_matches_new() {
    const AT_COMPILE_TIME: [ElectricInductance; 5] = [
        ElectricInductance::const_new(1234.5, ElectricInductanceUnit::Henry),
        ElectricInductance::const_new(1234.5, ElectricInductanceUnit::Picohenry),
        ElectricInductance::const_new(1234.5, ElectricInductanceUnit::Nanohenry),
        ElectricInductance::const_new(1234.5, ElectricInductanceUnit::Microhenry),
        ElectricInductance::const_new(1234.5, ElectricInductanceUnit::Millihenry),
    ];
    for (q, &unit) in AT_COMPILE_TIME.iter().zip(ElectricInductanceUnit::ALL) {
        assert_eq!(
            q.as_base().to_bits(),
            ElectricInductance::new(1234.5_f64, unit)
                .as_base()
                .to_bits(),
            "{unit:?}"
        );
    }
    for v in [0.0, -0.0, 1e-300, -2.5, 3.0e8, f64::MAX] {
        for &unit in ElectricInductanceUnit::ALL {
            assert_eq!(
                ElectricInductance::const_new(v, unit).as_base().to_bits(),
                ElectricInductance::<f64>::new(v, unit).as_base().to_bits()
            );
        }
    }
}

#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = ElectricInductance::from_base(v);
        let auto = q.auto_unit();
        assert_close(
            ElectricInductance::new(auto.value, auto.unit).as_base(),
            v,
            F64_TOL,
        );
        for &unit in ElectricInductanceUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        ElectricInductance::from_base(0.0).auto_unit().unit,
        ElectricInductanceUnit::Henry
    );
}

#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "H".parse::<ElectricInductanceUnit>(),
        Ok(ElectricInductanceUnit::Henry)
    );
    assert_eq!(
        format!("2.5 {}", "H").parse::<ElectricInductance>(),
        Ok(ElectricInductance::new(2.5, ElectricInductanceUnit::Henry))
    );
    assert_eq!(
        "pH".parse::<ElectricInductanceUnit>(),
        Ok(ElectricInductanceUnit::Picohenry)
    );
    assert_eq!(
        format!("2.5 {}", "pH").parse::<ElectricInductance>(),
        Ok(ElectricInductance::new(
            2.5,
            ElectricInductanceUnit::Picohenry
        ))
    );
    assert_eq!(
        "nH".parse::<ElectricInductanceUnit>(),
        Ok(ElectricInductanceUnit::Nanohenry)
    );
    assert_eq!(
        format!("2.5 {}", "nH").parse::<ElectricInductance>(),
        Ok(ElectricInductance::new(
            2.5,
            ElectricInductanceUnit::Nanohenry
        ))
    );
    assert_eq!(
        "µH".parse::<ElectricInductanceUnit>(),
        Ok(ElectricInductanceUnit::Microhenry)
    );
    assert_eq!(
        format!("2.5 {}", "µH").parse::<ElectricInductance>(),
        Ok(ElectricInductance::new(
            2.5,
            ElectricInductanceUnit::Microhenry
        ))
    );
    assert_eq!(
        "mH".parse::<ElectricInductanceUnit>(),
        Ok(ElectricInductanceUnit::Millihenry)
    );
    assert_eq!(
        format!("2.5 {}", "mH").parse::<ElectricInductance>(),
        Ok(ElectricInductance::new(
            2.5,
            ElectricInductanceUnit::Millihenry
        ))
    );
    assert_eq!(
        "1 not-a-unit".parse::<ElectricInductance>(),
        Err(ParseError::UnknownUnit)
    );
}

